"use client";

import { wedding } from "@/config/wedding";
import { ArabicText } from "@/components/decorative/Arabic";
import { Section } from "@/components/ui/Section";
import { SectionHeading } from "@/components/ui/SectionHeading";

export function WeddingDate() {
  const { month, year, days, arabicMonth, arabicYear } = wedding.date.display;

  return (
    <Section id="wedding-date">
      <SectionHeading
        label={wedding.copy.saveTheDate}
        arabic={wedding.arabic.saveTheDate}
      />
      <div className="date-block">
        <p className="date-month">{month}</p>
        <p className="date-year">{year}</p>
        {wedding.arabic.enabled ? (
          <ArabicText className="arabic-date-month" tone="calligraphy">
            {`${arabicMonth} ${arabicYear}`}
          </ArabicText>
        ) : null}
        <span className="date-rule" />
        <div className="date-pair">
          {days.map((item, index) => (
            <div className="date-pair-day" key={item.day}>
              {index > 0 ? (
                <span className={`date-pair-join${wedding.arabic.enabled ? " is-arabic" : ""}`} aria-hidden="true">
                  {wedding.arabic.enabled ? wedding.arabic.joiner : "&"}
                </span>
              ) : null}
              <div className="date-pair-col">
                <p className="date-weekday">{item.weekday}</p>
                {wedding.arabic.enabled ? (
                  <ArabicText className="arabic-weekday" tone="calligraphy">
                    {item.arabicWeekday}
                  </ArabicText>
                ) : null}
                <p className="date-day">{item.day}</p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </Section>
  );
}
