"use client";

import { useEffect, useState } from "react";
import { ArabicText } from "@/components/decorative/Arabic";
import { wedding } from "@/config/wedding";
import { getCountdown } from "@/lib/countdown";
import { pad } from "@/lib/format";
import { Section } from "@/components/ui/Section";
import { SectionHeading } from "@/components/ui/SectionHeading";

export function Countdown() {
  const [now, setNow] = useState<number | null>(null);

  useEffect(() => {
    const tick = () => setNow(Date.now());
    tick();
    const id = window.setInterval(tick, 1000);
    return () => window.clearInterval(id);
  }, []);

  const parts = getCountdown(wedding.date.iso, now ?? 0);
  const ready = now !== null;

  const cells = [
    {
      value: ready ? pad(parts.days, parts.days > 99 ? 3 : 2) : "—",
      label: "Days",
      arabic: wedding.arabic.countdown.days,
    },
    {
      value: ready ? pad(parts.hours) : "—",
      label: "Hours",
      arabic: wedding.arabic.countdown.hours,
    },
    {
      value: ready ? pad(parts.minutes) : "—",
      label: "Minutes",
      arabic: wedding.arabic.countdown.minutes,
    },
    {
      value: ready ? pad(parts.seconds) : "—",
      label: "Seconds",
      arabic: wedding.arabic.countdown.seconds,
    },
  ];

  return (
    <Section id="countdown">
      <SectionHeading
        label={wedding.copy.countdownLabel}
        arabic={wedding.arabic.untilWeCelebrate}
      />
      {wedding.arabic.enabled ? (
        <ArabicText className="arabic-quiet" tone="calligraphy">
          {wedding.arabic.inshaAllah}
        </ArabicText>
      ) : null}
      <div className="countdown" aria-live="polite">
        {cells.map((cell) => (
          <div className="countdown-cell" key={cell.label}>
            <p className="countdown-value">{cell.value}</p>
            <p className="countdown-unit">{cell.label}</p>
            {wedding.arabic.enabled ? (
              <p className="countdown-unit-ar" lang="ar" dir="rtl">
                {cell.arabic}
              </p>
            ) : null}
          </div>
        ))}
      </div>
      {ready && parts.complete && (
        <>
          {wedding.arabic.enabled ? (
            <ArabicText className="arabic-kicker" tone="calligraphy">
              {wedding.arabic.alhamdulillah}
            </ArabicText>
          ) : null}
          <p className="countdown-complete">The celebration has begun.</p>
        </>
      )}
    </Section>
  );
}
