"use client";

import { ArabicText } from "@/components/decorative/Arabic";
import { Section } from "@/components/ui/Section";
import { SectionHeading } from "@/components/ui/SectionHeading";
import { MapButton } from "@/components/ui/MapButton";
import { CalendarButton } from "@/components/ui/CalendarButton";
import { venueFullAddress, wedding } from "@/config/wedding";

export function VenueSection() {
  const mainEvent = wedding.events.find((event) => event.id === "wedding") ?? wedding.events[0];

  return (
    <Section id="venue">
      {wedding.arabic.enabled ? (
        <ArabicText className="arabic-kicker" tone="calligraphy">
          {wedding.arabic.welcome}
        </ArabicText>
      ) : null}
      <SectionHeading
        label={wedding.copy.venueHeading}
        arabic={wedding.arabic.theVenue}
      />
      <h2 className="venue-name">{wedding.venue.name}</h2>
      <p className="venue-address">{venueFullAddress()}</p>
      <p className="place-line" style={{ marginTop: "1rem" }}>
        {wedding.venue.dateLabel}
      </p>
      {wedding.venue.timeLabel ? (
        <p className="place-line">{wedding.venue.timeLabel}</p>
      ) : null}
      <div className="event-actions">
        <MapButton />
        <MapButton directions />
        {mainEvent ? <CalendarButton event={mainEvent} /> : null}
      </div>
    </Section>
  );
}
